        auth.realm().requireManageRealm();

        logger.debugf("updating realm: %s", realm.getName());

        if (Config.getAdminRealm().equals(realm.getName()) && (rep.getRealm() != null && !rep.getRealm().equals(Config.getAdminRealm()))) {
